    "questionText": "Shannon capacity increases with:",
    "options": [
      {
        "id": "A",
        "optionId": "A",
        "text": "Bandwidth and logarithmically with SNR"
      },
      {
        "id": "B",
        "optionId": "B",
        "text": "Temperature only"
      },
      {
        "id": "C",
        "optionId": "C",
        "text": "Screen size"
      },
      {
        "id": "D",
        "optionId": "D",
        "text": "RAM frequency only"
      }
    ],
    "correctOption": "A",
    "explanation": "Shannon-Hartley theorem states C = B * log2(1 + SNR), showing capacity scales linearly with bandwidth B and logarithmically with signal-to-noise ratio.",
